  "x6775": {"q":"解析說為什麼填「流星」而不是「水星」「木星」？","o":["因為流星比較亮", "因為彗星有尾巴", "因為流星每天都有", "由「滑過」「橫掃且直落」可知取其瞬間掠過的意象；水星、木星為行星，不會劃過夜空"],"a":3},
  "x6776": {"q":"解析說「永垂不朽」是什麼意思？「功敗垂成」為什麼不合？","o":["「永垂不朽」指名聲、事蹟永遠流傳而不磨滅；「功敗垂成」指事情將成功時失敗，語意相反", "「永垂不朽」指長生不老；「功敗垂成」指功成名就", "「永垂不朽」指作品保存完好；「功敗垂成」指半途而廢", "兩者語意相近，皆可填入"],"a":0},
