  "x6779": {"q":"解析說兩個空格為什麼填「選擇」和「藝術」？","o":["因為「看見」與「戰爭」都是登山用語", "因為「想像」與「嘗試」語意相近", "因為「要求」與「知識」搭配得當", "因為與「放棄」相對的是「選擇」；「是一門……」後接「藝術」為固定搭配"],"a":3},
