  "x11118": {"q":"解析說「人非聖賢」為什麼算句子？","o":["「人」為主語，「非聖賢」為謂語，具備完整的主語與謂語", "因為它字數最多", "因為它出自古書", "因為它有否定詞"],"a":0},
  "x11121": {"q":"解析說「山川壯麗，物產豐隆」屬於什麼句型？","o":["屬於敘事句", "以「壯麗」「豐隆」說明主語的性質狀態，屬表態句", "屬於有無句", "屬於判斷句"],"a":1},
  "x11123": {"q":"解析說「強將手下無弱兵」屬於什麼句型？為什麼？","o":["屬表態句，因為有形容詞", "屬判斷句，因為有繫詞", "述語是「無」，屬有無句", "屬敘事句，因為有動作"],"a":2},
  "x11124": {"q":"解析說「有情人終成眷屬」為什麼不是有無句？","o":["因為它沒有主語", "因為它的述語是「有」", "因為它是判斷句", "主語是「有情人」，述語是「成」（成為），並非以「有」「無」為述語，屬敘事句"],"a":3},
  "x11126": {"q":"解析說其他三句為什麼是判斷句？","o":["因為皆以繫詞「為」「非」「是」連接主語與斷語", "因為皆有明確的動作", "因為皆以「有」「無」為述語", "因為皆用形容詞說明狀態"],"a":0},
