  "x11211": {"q":"解析說作者由傘的功能寫到什麼？暗喻什麼？","o":["寫到傘的材質，暗喻做人要堅韌", "寫到雨天的不便，暗喻人生多舛", "寫到心的寧靜、怡然，暗喻無論處在順、逆境，都能收放自如", "寫到朋友的扶持，暗喻患難見真情"],"a":2},
  "x11212": {"q":"解析說「土地乾裂」為什麼不是文中的景象？","o":["因為文中只寫了牛群", "因為那是作者刻意省略的", "因為那出現在別的段落", "因為土地乾裂是久旱的景象，與雷雨交加的情境不合"],"a":3},
