  "x11215": {"q":"解析說本文主要用什麼手法鋪陳？對話占多少？","o":["主要用議論說理，對話占大半", "主要以敘述與描寫鋪陳往事，對話僅零星穿插", "主要用書信體，全篇皆為對話", "主要用日記體，完全沒有對話"],"a":1},
