  "x14960": {"q":"解析說旅行讓什麼成為安藤忠雄的老師？","o":["透過旅行，全世界的建築鉅作都跳出教科書，成為他的老師", "透過旅行，各國的建築師親自教導他", "透過旅行，當地的工匠成為他的老師", "透過旅行，大學教授收他為徒"],"a":0},
