  "x15086": {"q":"解析說題幹與哪一個選項的主題相同？","o":["與「他鄉的雨，和著母親的淚」相同，都寫思鄉", "與「瓦背上嘩嘩的雨聲」相同，都寫童年", "與「廝守到永遠」相同，都寫熱戀", "與「失戀雨無緣無故無情淋著我的愛」相同，皆描寫失戀"],"a":3},
  "x15088": {"q":"解析說作者對蜜蜂的排斥來自什麼？","o":["由「覺得那蜜蜂可憐，原諒牠了。可是……總不怎麼舒服」可知，排斥並非理性判斷，而是來自童年創傷經驗所留下的主觀情緒", "來自對蜜蜂習性的理性判斷", "來自蜜蜂沒有實用價值", "來自對蜜蜂了解得太少"],"a":0},
