  "x15100": {"q":"解析引用哪一句說明老學者的心情？","o":["由「渴望在有生之年再度來臺」單句可知", "由「一睹郡大林道」可知", "由「當他耄耋孱弱的身軀挺立在山上之際，所見者卻是百般凋殘的死亡大地」可知", "由「戰後被遣送回國」可知"],"a":2},
