  "x15113": {"q":"解析說文中用哪些語句形象化地描寫什麼？","o":["用「地氣」寫火山活動", "用「一鍋杜鵑」、「地氣熬了一個冬天」、「沸沸揚揚」等語句，形象化地描述杜鵑花在春天盛開的景象", "用「噴紅濺紫」寫鳥類飛翔", "用「三月裡」寫氣候變化"],"a":1},
  "x15116": {"q":"解析說兩個空格各憑什麼推知？","o":["由「六月早晨」推知第一格填「連」", "由「重回夢鄉」推知第二格填「變化多端」", "由「完全與背景□在一起，真正的變色蜥蜴」可知記憶能融入背景，宜填「融」；由「我可以聽到它們呼吸」可知環境嘈雜記憶仍清晰，宜填「震耳欲聾」", "由押韻決定兩格用字"],"a":2},
  "x15118": {"q":"解析從溺水者的舉動看出他什麼態度？","o":["看出他慌亂無措", "看出他不信任同伴", "看出他貪生怕死", "由溺水者明知錢財拖累自己仍搖頭不願拋棄，最終溺死，可見其嗜財如命、執迷不悟"],"a":3},
  "x15121": {"q":"解析說題幹與哪一句手法相同？是什麼手法？","o":["與「蟬噪林愈靜，鳥鳴山更幽」相同，皆藉聲音的描寫來反襯四周的寂靜", "與「胡馬依北風」相同，皆寫思鄉", "與「返景入深林」相同，皆寫光影", "與「感時花濺淚」相同，皆寫傷時"],"a":0},
