  "x20382": {"q":"解析說「怨天尤人」的「尤」是什麼意思？為什麼容易寫錯？","o":["「尤」指從、因為，與「由」意思相同", "「尤」指猶如，容易與「猶」混", "「尤」指游泳，容易與「游」混", "「尤」在此指責怪、歸咎；「由」指從、因為，同一句中「由於」與「尤人」兩字容易互換寫錯"],"a":3},
