  "x20452": {"q":"解析說「繁」的本義與引申義各是什麼？","o":["「繁」指平凡、凡是", "「繁」從糸，本義為馬頭上的裝飾，引申為多、盛；「凡」指平凡、凡是", "「繁」從火，本義為煩惱", "「繁」從石，本義為明礬"],"a":1},
