  "x20868": {"q":"解析說「歸」的本義與引申義各是什麼？","o":["「歸」從止從帚，本義為女子出嫁，引申為返回、歸屬；「規」從見從夫，指規則", "「歸」指規則，「規」指返回", "兩者意思相同", "「歸」是烏龜，「規」是窺視"],"a":0},
