  "x20886": {"q":"解析說「鏗」的本義是什麼？「吭」呢？","o":["「鏗」從口指喉嚨，「吭」從金指撞擊聲", "兩者意思相同", "「鏗」從金，本義為金屬撞擊聲；「吭」從口，指喉嚨", "「鏗」是坑洞，「吭」是高亢"],"a":2},
