  "x1835": {"q":"解析說「鏟」子的部首與意思是什麼？","o":["「鏟」子＝挖土工具（金部）","從刀部，指剷除","兩者相同","從立部，指生產"],"a":0},
  "x1846": {"q":"解析說鍋「鏟」的部首與意思是什麼？「產」又是什麼？","o":["鏟是生產","鍋「鏟」＝炒菜工具（金部）；產＝生產","兩者相同","鏟從立部"],"a":1},
  "x1847": {"q":"解析說「錄」音的部首與意思是什麼？","o":["從示部，指俸祿","從糸部，指綠色","「錄」音＝記錄聲音（金部）","兩者相同"],"a":2},
