  "x1852": {"q":"解析說山「巒」的部首與意思是什麼？","o":["從木部，指欒樹","山「巒」＝連綿的山（山部）","兩者相同","從金部，指車鈴"],"a":1},
  "x1853": {"q":"解析說「縱」谷的部首與意思是什麼？","o":["從足部，指蹤跡","從山部，指山谷","「縱」谷＝與山脈平行的谷地（糸部）","兩者相同"],"a":2},
  "x1859": {"q":"解析說「綠」意的部首與意思是什麼？","o":["從金部，指記錄","從示部，指俸祿","兩者相同","「綠」意＝綠色生機（糸部）"],"a":3},
  "x1861": {"q":"解析說「孿」生的部首與意思是什麼？","o":["「孿」生＝雙胞胎（子部）","從山部，指山巒","兩者相同","從心部，指愛戀"],"a":0},
  "x1863": {"q":"解析說「歷久不衰」是什麼意思？","o":["＝時間很短","歷久不「衰」＝長久不衰退","兩者相同","＝從內心發出"],"a":1},
  "x1865": {"q":"解析說「言不由衷」是什麼意思？","o":["＝說話很衰弱","＝說話很悲哀","言不由「衷」＝話不是發自內心","兩者相同"],"a":2},
  "x1866": {"q":"解析說「無濟於事」的「濟」部首與意思是什麼？","o":["從手部，指擁擠","從月部，指肚臍","兩者相同","無「濟」於事＝沒有幫助（氵部）"],"a":3},
  "x1872": {"q":"解析說「老弱殘兵」是什麼意思？「殘」的部首是什麼？","o":["老弱「殘」兵＝衰弱無戰力的士兵（歹部）","＝年輕強壯的士兵","兩者相同","殘從足部"],"a":0},
  "x1880": {"q":"解析說「腳踏實地」是什麼意思？","o":["＝一步登天","「腳踏實地」＝做事切實穩健","兩者相同","＝好高騖遠"],"a":1},
