  "x1892": {"q":"解析說「林立」是什麼意思？","o":["＝只有一家","＝樹木倒下","兩者相同","「林立」＝像樹林般密集，比喻眾多"],"a":3},
  "x1893": {"q":"解析說比喻句結束與引出內心話各用什麼標點？","o":["句中停頓用逗號；「車子一如甲蟲」一個完整比喻後用句號；「喊著」後引出內心話用冒號加引號，讚嘆語氣用驚嘆號收在引號內","全部用逗號","兩者相同","引出內心話用破折號"],"a":0},
  "x1894": {"q":"解析說並列動作與句意完結各用什麼標點？","o":["並列動作用逗號","「閃耀、移動」並列動作用頓號；其後語氣停頓用逗號；「那麼明亮」句意完結用句號；後半句中停頓用逗號、句末句號","兩者相同","句意完結用驚嘆號"],"a":1},
  "x1895": {"q":"解析說引出引文與引文結束各用什麼標點？","o":["引出引文用破折號","引文末尾句號放引號外","「旁白」後引出引文用冒號加引號；引文中間停頓用逗號、末尾句號放在引號內；引文結束後接續句子用逗號","兩者相同"],"a":2},
  "x1896": {"q":"解析說標語與說話內容各怎麼標點？","o":["標語用書名號","說話內容用破折號","兩者相同","句中停頓用逗號；「腳踏實地愛臺灣」是引述的標語加引號；「對你說」後用冒號加引號引出說話內容"],"a":3},
  "x1897": {"q":"解析說「多點美麗，少點哀愁」怎麼標點？","o":["「多點美麗，少點哀愁」句中停頓用逗號、語意完結用句號；「天災難以躲過，人禍卻能避免」同樣逗號加句號","中間用頓號","兩者相同","中間用分號"],"a":0},
