  "x1919": {"q":"解析說人「禍」的部首與意思是什麼？「或」又是什麼？","o":["人「禍」＝人為災禍（示部）；或＝或者","禍從金部","兩者相同","禍是或者"],"a":0},
  "x1920": {"q":"解析說流「血」的「血」跟「寫」怎麼分？","o":["血是書寫","解析寫的是流「血」；寫＝書寫","兩者相同","寫是血液"],"a":1},
  "x1921": {"q":"解析說「抱殘守缺」是褒義還是貶義？這句話該用什麼？","o":["是褒義，用得正確","可以用在勸勉","「抱殘守缺」＝固守舊事物不知變通，是貶義詞，與勸勉語意不合，應用「腳踏實地」","兩者相同"],"a":2},
  "x1922": {"q":"解析說「哀愁」與「悲哀」的「哀」意思相同嗎？","o":["不同，一個是悼念","不同，一個是衰弱","兩者相同","「哀愁」與「悲哀」的哀都是「悲傷」的意思"],"a":3},
  "x1923": {"q":"解析說作者呼籲大家做什麼？","o":["作者是「呼籲大家一起為家園的美好努力、善待土地」，不是呼籲大家加入空拍","呼籲大家去學空拍","兩者相同","呼籲大家買攝影機"],"a":0},
  "x1924": {"q":"解析說「檳」與「榔」的部首是什麼？","o":["都是貝部","「檳」「榔」都是木部（樹木類植物）","兩者相同","都是邑部"],"a":1},
  "x1925": {"q":"解析說「錄」與「碌」相同的部件是什麼？","o":["相同的是金字旁","相同的是石字旁","「錄」（金＋彔）與「碌」（石＋彔）相同的部件是聲符「彔」","兩者相同"],"a":2},
  "x1926": {"q":"解析說「縱谷」與「縱火」的「縱」讀音相同嗎？","o":["相同，都讀四聲","相同，都讀一聲","兩者相同","「縱谷」的縱讀ㄗㄨㄥ（一聲）；「縱火」的縱讀ㄗㄨㄥˋ（四聲，同「粽」音），聲調不同"],"a":3},
  "x1927": {"q":"解析說作者辭職專心空拍的關鍵事件是什麼？","o":["作者辭職專心空拍的關鍵是「莫拉克颱風」帶來的衝擊，不是森林大火","關鍵是一場森林大火","兩者相同","關鍵是地震"],"a":0},
  "x1928": {"q":"解析說「歹＋戔」組成什麼字？部首是什麼？","o":["組成「踐」，部首是足","歹＋戔＝「殘」，部首是歹部（與死傷有關）","兩者相同","組成「賤」，部首是貝"],"a":1},
  "x1929": {"q":"解析說「子子孫孫」是什麼意思？","o":["＝每家每戶","＝各行各業","「子子孫孫」＝世代綿延不絕的後裔","兩者相同"],"a":2},
  "x1930": {"q":"解析說「檳」與「濱」的注音是什麼？","o":["檳讀ㄅㄧㄥ","兩字讀音不同","兩者相同","「檳」與「濱」都讀ㄅㄧㄣ"],"a":3},
  "x1931": {"q":"解析說作者空拍的目的是什麼？","o":["作者空拍是想記錄臺灣的美麗與哀愁、喚起環保意識，不是為了向外國宣傳觀光","目的是向外國宣傳觀光","兩者相同","目的是賺錢"],"a":0},
  "x1932": {"q":"解析說影片想讓大家珍惜什麼？","o":["珍惜時間","影片想讓大家珍惜「土地／環境」，不是珍惜時間","兩者相同","珍惜金錢"],"a":1},
  "x1933": {"q":"解析說「降低」與「投降」的「降」讀音相同嗎？","o":["相同，都讀ㄐㄧㄤˋ","相同，都讀ㄒㄧㄤˊ","「降低」的降讀ㄐㄧㄤˋ；「投降」的降讀ㄒㄧㄤˊ（與「祥」同音），兩者不同","兩者相同"],"a":2},
  "x1934": {"q":"解析說「禍」與「鍋」的部首各是什麼？","o":["都是口部","都是示部","兩者相同","「禍」是示部；「鍋」是金部，都不是口部"],"a":3},
  "x1935": {"q":"解析說時間悄悄流逝該用哪個成語？用得對不對？","o":["時間悄悄流逝用「無聲無息」，使用正確","應改用生生不息","兩者相同","應改用川流不息"],"a":0},
